-- Subject-aware Physics 7 Chapter IV draft foundation, Sprint 15D.2.
-- Owner accepted the 236-slot three-batch plan and delegated ordinary approvals on 2026-10-17.
-- This creates review-only curriculum data, not an assessment contract or release.
-- Existing migrations, existing curriculum, learner data and runtime
-- prerequisites are untouched. All content and specialist gates remain pending.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
do $pre$ begin
 if exists(select 1 from public.units where code='PHY7-U04')
 or exists(select 1 from public.skills where code like 'PHY7-U04-%')
 then raise exception '15D2 refuses to overwrite an existing Chapter IV'; end if;
 if (select count(*) from public.subject_program_source_bindings b join public.units u on u.subject_program_id=b.subject_program_id where u.code='PHY7-U02' and b.applicability_status='governing')<>1 then raise exception '15D2 governing source binding required'; end if;
end $pre$;
do $post$ begin if (select count(*) from public.curriculum_release_skills where curriculum_release_id='18eb78e8-79f7-5307-bef2-38c4baa1d809'::uuid)<>14 or (select count(*) from public.curriculum_release_outcomes where curriculum_release_id='18eb78e8-79f7-5307-bef2-38c4baa1d809'::uuid)<>13 then raise exception '15D2 incomplete draft foundation'; end if; end $post$;
commit;
